function imageGallery(title,description,images){return `<section class="section"><div class="wrap grid image-gallery">${images.map(([name,img])=>`<article class="card image-card"><div class="service-photo"><img class="${/Plan|floor-plan/i.test(img)?'plan-img':''}" src="/images/${img}" alt="${name} — Divyanshu Infratech" loading="lazy"></div><h3>${name}</h3></article>`).join('')}</div></section>`}
function vastuPage(){
 const zones=[['N','North','Living / Entry','Opportunity'],['NNE','North-North-East','Meditation / Study',''],['NE','North-East','Pooja / Water','Light'],['ENE','East-North-East','Study / Activity',''],['E','East','Living / Dining','Energy'],['ESE','East-South-East','Utility / Dining',''],['SE','South-East','Kitchen / Fire','Agni'],['SSE','South-South-East','Storage / Utility',''],['S','South','Stair / Storage','Strength'],['SSW','South-South-West','Heavy Storage',''],['SW','South-West','Master Bedroom','Stability'],['WSW','West-South-West','Bedroom / Storage',''],['W','West','Bedroom / Study','Support'],['WNW','West-North-West','Guest / Toilet',''],['NW','North-West','Guest / Parking','Movement'],['NNW','North-North-West','Movement / Storage','']];
 const keyPoints=[['Entrance','North, North-East or East are commonly preferred.'],['Kitchen','South-East is commonly preferred.'],['Master Bedroom','South-West is commonly preferred.'],['Pooja Room','North-East is commonly preferred.'],['Underground Tank','North-East is commonly preferred.'],['Staircase','South, South-West or West are commonly preferred.'],['Toilet','West or North-West are commonly preferred.'],['Open Space','Keep North and East comparatively open.']];
 const facings=[['North','N','North / North-East','Keep North and East comparatively open.'],['East','E','East / North-East','Give importance to light and openness toward East.'],['South','S','Prefer a carefully selected South-East-side zone','Entrance position needs more careful planning than simply choosing a side.'],['West','W','West / North-West','North-West can work well for entry and parking planning.']];
 const entranceSides=[['North','N','Use the exact entrance sector only after checking the full floor plan and site orientation.'],['East','E','East-facing entrances should be checked by sector rather than by facing name alone.'],['South','S','South-facing entrances need careful sector selection and complete layout review.'],['West','W','West-facing entrances can work well when the exact sector and internal zoning are balanced.']];
 const roomSizes=[['Bedroom','10 × 12 ft to 14 × 16 ft','Allow space for bed circulation, wardrobe and natural ventilation.'],['Kitchen','7 × 10 ft to 10 × 12 ft','Plan a practical work triangle along with the preferred Vastu zone.'],['Toilet / Bathroom','Minimum around 4 × 7 ft','Keep plumbing efficiency, ventilation and privacy in mind.'],['Living Room','Around 12 × 14 ft and above','Size should respond to seating, circulation and family usage.']];
 const checklist=['Confirm the plot’s actual dimensions before final planning.','Confirm the road/front direction with a reliable compass or site survey.','Keep the North-East lighter and more open where practical.','Prefer the kitchen toward the South-East zone where feasible.','Prefer the master bedroom toward the South-West zone.','Avoid placing toilets in the North-East where possible.','Check setbacks, ventilation, structure and local building rules before freezing the plan.'];
 return `<main class="vastu-page"><section class="vastu-hero"><div class="wrap"><div class="eyebrow">DIVYANSHU INFRATECH · VASTU SHASTRA</div><h1>Vastu Planning Tool</h1><h2>Enter Your Plot Size.<br>Get Vastu Suggestions.</h2><p>Enter your plot length, width and front direction to get instant preliminary Vastu suggestions for important rooms and services.</p><div class="vastu-hero-points"><span>Length &amp; Width</span><span>Plot Facing</span><span>Instant Guide</span></div></div></section>
 <section class="section vastu-calculator-section"><div class="wrap vastu-calculator-layout"><div class="vastu-calculator-card"><div class="vastu-calculator-heading"><span class="vastu-free-tag">FREE</span><div class="eyebrow">FREE VASTU CALCULATOR</div><h2>Enter Plot Details</h2><p>Only 3 details required: plot length, plot width and the road/front direction.</p></div><form id="vastu-calculator" class="vastu-calculator"><label>Plot Length<div class="vastu-input-unit"><input type="number" name="length" min="1" max="10000" step="any" placeholder="e.g. 60" required><span>ft</span></div></label><label>Plot Width<div class="vastu-input-unit"><input type="number" name="width" min="1" max="10000" step="any" placeholder="e.g. 40" required><span>ft</span></div></label><label>Plot Front / Road Direction<select name="facing" required><option value="">Select plot front / facing</option><option value="North">North</option><option value="East">East</option><option value="South">South</option><option value="West">West</option></select></label><div class="vastu-form-actions"><button class="btn" type="submit">Get Vastu Suggestion</button><button class="btn outline" type="reset">Reset</button></div><p class="vastu-disclaimer">Preliminary direction-based planning guidance. Final placement should be checked against the actual floor plan and site.</p></form></div><div class="vastu-result-card" id="vastu-result" aria-live="polite"><div class="eyebrow">VASTU ZONE PREVIEW</div><h2>Your preliminary guide will appear here</h2><p>Enter your plot measurements and facing direction to view a first-pass suggestion.</p><div class="vastu-mini-grid"><span>NW</span><span>N</span><span>NE</span><span>W</span><b>CENTER</b><span>E</span><span>SW</span><span>S</span><span>SE</span></div></div></div></section>
 <section class="section soft"><div class="wrap">${sectionTitle('SIMPLE PLANNING PROCESS','From Plot Measurement to Vastu Zoning','Start with reliable measurements and direction. The calculator converts those inputs into a simple preliminary zoning guide.')}<div class="grid vastu-process">${[['01','Measure Your Plot','Enter the actual plot length and width so the tool can understand the proportion and total area.'],['02','Choose the Front Direction','Select the side where your plot faces the road/front. Correct direction is important for preliminary zoning.'],['03','Get Suggested Zones','See suggested directions for entrance, kitchen, bedrooms, pooja, staircase, water tanks and parking.']].map(([n,t,d])=>`<article class="card"><span class="vastu-step-no">${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>
 <section class="section"><div class="wrap vastu-direction-intro"><div><div class="eyebrow">DIRECTION FIRST</div><h2>A Good Vastu Plan Starts With Accurate Orientation</h2><p>Plot facing alone does not determine the complete plan. Entrance position, room zoning, open space, services and circulation all need to work together with the actual site.</p><ul>${['Actual plot length and width','Correct North / road direction','Room and floor requirements','Setback and ventilation needs'].map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="vastu-zone-preview"><div class="eyebrow">VASTU ZONE PREVIEW</div><h3>Simple 3 × 3 Planning Grid</h3><div class="vastu-3x3">${[['NW','Guest / Toilet','Movement'],['N','Living / Entry','Opportunity'],['NE','Pooja / Water','Light'],['W','Children / Study','Support'],['CENTER','Lobby / Open','Brahmasthan'],['E','Living / Dining','Energy'],['SW','Master Bedroom','Stability'],['S','Stair / Storage','Strength'],['SE','Kitchen','Agni']].map(([a,b,c])=>`<div><b>${a}</b><strong>${b}</strong><small>${c}</small></div>`).join('')}</div><p class="vastu-caption">This grid is a simplified visual guide. Exact room placement depends on the real plot, building footprint, setbacks and project requirements.</p></div></div></section>
 <section class="section soft"><div class="wrap">${sectionTitle('16 DIRECTION ZONES','Understand Your Plot Through 16 Vastu Zones','A 16-zone view gives a more detailed picture than the basic 8 directions. It helps you understand where rooms, services and movement areas may fall within the plan.')}<div class="vastu-compass-layout"><div class="vastu-compass"><div class="vastu-compass-ring"><span class="compass-center">BRAHMA<br>STHAN</span>${zones.map(([d])=>`<span class="compass-dir compass-${d.toLowerCase()}">${d}</span>`).join('')}</div><h3>16-Zone Compass</h3><p>Detailed Direction Map</p></div><div class="vastu-zone-list"><h3>What Each Zone Commonly Supports</h3><div class="grid">${zones.map(([d,name,place,quality])=>`<article class="vastu-zone-item"><b>${d}</b><div><strong>${name}</strong><span>${place}</span>${quality?`<small>${quality}</small>`:''}</div></article>`).join('')}</div></div></div><p class="vastu-caption">The 16-zone compass is a planning guide, not an automatic approval. Exact room placement still depends on your actual floor plan, road position, setbacks, structure, ventilation and room requirements.</p></div></section>
 <section class="section"><div class="wrap vastu-mandala-layout"><div><div class="eyebrow">VASTU PURUSHA MANDALA</div><h2>Understand the Energy Grid of a Plan</h2><p>The Vastu Purusha Mandala is a traditional planning grid used to understand the center, directions and functional zones of a building. It helps explain how the Brahmasthan and surrounding directional areas relate to the overall layout.</p><div class="vastu-mandala-visual" role="img" aria-label="Original educational Vastu Purusha Mandala diagram showing Brahmasthan and directional planning zones"><div class="mandala-grid">${Array.from({length:25},(_,i)=>`<span class="${i===12?'mandala-center':''}">${i===12?'BRAHMASTHAN':(['N','NE','E','SE','S','SW','W','NW'][Math.floor(i/3)%8]||'')}</span>`).join('')}</div><strong>VASTU PURUSHA MANDALA</strong><small>Directional planning reference</small></div><p class="vastu-caption">This original diagram is for educational and preliminary planning guidance.</p></div><div class="vastu-mandala-notes"><div class="eyebrow">HOW TO READ THE MANDALA</div><h3>Center, Directions and Functional Planning Zones</h3><p>The Mandala is best understood as a reference grid. The center is commonly associated with the Brahmasthan, while the surrounding sectors represent different directional areas used during preliminary space planning.</p>${[['Brahmasthan','The central part of the building footprint. It is generally kept comparatively light and unobstructed where practical.'],['Directional Zones','North, East, South, West and intermediate directions are used to understand room and service placement.'],['Planning Grid','The Mandala provides a visual framework for checking how the building layout relates to the directional zones.'],['Final Verification','Always coordinate Vastu preferences with structure, setbacks, ventilation, circulation and local building rules.']].map(([t,d])=>`<article><b>${t}</b><p>${d}</p></article>`).join('')}<aside><strong>Important for Your Floor Plan Analyzer</strong><p>When you upload a floor plan on the result page, align the Vastu compass with the actual North direction and place the center over the built-up footprint. This makes the Mandala concept easier to understand visually.</p></aside></div></div></section>
 <section class="section soft"><div class="wrap">${sectionTitle('ENTRANCE PLANNING','Explore the 32 Entrance Zones','Each side of a plot can be divided into eight smaller entrance sectors. This helps you look beyond only “North-facing” or “East-facing” and review the exact entrance location more carefully.')}<div class="vastu-32-banner">4 Sides × 8 Zones = 32</div><div class="grid vastu-entrance-grid">${entranceSides.map(([side,letter,note])=>`<article class="card vastu-entrance-card"><div class="eyebrow">ENTRANCE SIDE</div><h3>${side} Side</h3><div class="entrance-compass">${letter}</div><div class="entrance-zones">${Array.from({length:8},(_,i)=>`<span>${letter}${i+1}</span>`).join('')}</div><p>${note}</p></article>`).join('')}</div><div class="vastu-entrance-note"><h3>Entrance Position Matters More Than Facing Name Alone</h3><p>A plot may face North, East, South or West, but the exact door position within that side can change the planning approach. Use the 32-zone guide as a detailed reference before finalizing the entrance.</p><h4>Before Finalizing Entrance</h4><ul>${['Confirm actual North direction on site','Check the exact road/front position','Check setback and gate alignment','Review staircase and circulation','Check internal room arrangement','Confirm structural feasibility'].map(x=>`<li>${x}</li>`).join('')}</ul></div></div></section>
 <section class="section"><div class="wrap vastu-center-layout"><div class="vastu-center-diagram"><div class="center-square"><span>N</span><span>E</span><b>BRAHMA<br>STHAN</b><span>W</span><span>S</span></div><div class="eyebrow">CENTER OF THE PLAN</div><h2>Brahmasthan</h2></div><div><div class="eyebrow">CENTER ZONE GUIDANCE</div><h2>Keep the Center Simple and Balanced</h2><p>The Brahmasthan is the central zone of the building layout. In a preliminary Vastu plan, it is commonly treated as a lighter, less obstructed area so circulation and spatial balance remain clear.</p><div class="grid vastu-guidance-grid">${[['Keep Comparatively Open','Avoid unnecessary heavy obstruction in the central zone where practical.'],['Support Easy Circulation','Use the center to improve movement between living, dining and connecting spaces.'],['Avoid Toilet in Center','Try to keep toilet and major plumbing away from the exact center where feasible.'],['Coordinate With Structure','Final center planning must still respect columns, beams and structural requirements.']].map(([t,d])=>`<article class="card"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><p class="vastu-caption">The exact Brahmasthan position should be identified from the actual building footprint, not only the full plot boundary.</p></div></div></section>
 <section class="section soft"><div class="wrap">${sectionTitle('FACING-WISE GUIDE','Quick Ideas for the Four Main Facings','Every facing can be planned well. The more important question is how the entrance and internal spaces are positioned within that facing.')}<div class="vastu-facing-label">North • East • South • West</div><div class="grid vastu-facing-grid">${facings.map(([name,letter,entry,note])=>`<article class="card vastu-facing-card"><div class="eyebrow">PLOT FACING</div><h3>${name} Facing</h3><div class="facing-compass">${letter}</div><dl><dt>Entrance</dt><dd>${entry}</dd><dt>Kitchen</dt><dd>South-East</dd><dt>Master Bed</dt><dd>South-West</dd></dl><p>${note}</p></article>`).join('')}</div><p class="vastu-caption"><strong>Important:</strong> A North, East, South or West facing property is not automatically good or bad. Entrance location and complete space arrangement matter more than the facing label alone.</p></div></section>
 <section class="section"><div class="wrap">${sectionTitle('VASTU KEY POINTS','Important Home Planning Directions','These are commonly used preliminary Vastu zoning guidelines for residential planning.')}<div class="grid vastu-key-grid">${keyPoints.map(([t,d])=>`<article class="card"><span class="vastu-check">✓</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>
 <section class="section soft"><div class="wrap">${sectionTitle('PRACTICAL PLANNING','Vastu Also Needs Functional Room Sizes','Direction is only one part of a good home. Rooms must also be comfortable enough for furniture, movement, ventilation and daily use.')}<div class="grid vastu-room-grid">${roomSizes.map(([t,size,d])=>`<article class="card"><h3>${t}</h3><strong class="room-size">${size}</strong><p>${d}</p></article>`).join('')}</div></div></section>
 <section class="section"><div class="wrap vastu-checklist-layout"><div><div class="eyebrow">BEFORE FINALIZING</div><h2>Vastu Planning Checklist</h2><p>Use these checks before freezing a residential floor plan. Confirm each item against the actual site and building requirements.</p></div><ol>${checklist.map((x,i)=>`<li><b>${i+1}</b><span>${x}</span></li>`).join('')}</ol></div></section>
 <section class="section vastu-cta-section"><div class="wrap vastu-cta"><div class="eyebrow">DISCUSS MY PLOT WITH AN EXPERT</div><h2>Need an Exact Vastu<br>Floor Plan for Your Plot?</h2><p>Share your plot dimensions, facing, floor requirements and room requirements with our team for a detailed project-specific layout.</p><div class="vastu-cta-points"><span>Plot Review</span><span>Direction Guidance</span><span>Room-wise Planning</span></div><div class="hero-actions"><a class="btn" target="_blank" rel="noopener noreferrer" href="https://wa.me/919304867172?text=Hello%20Divyanshu%20Infratech%2C%20I%20would%20like%20a%20Vastu%20consultation%20for%20my%20plot.">Get Vastu Consultation</a><button class="btn outline" type="button" data-consultation-open>Discuss your plot, floor plan and requirements with our team</button></div></div></section></main>`
}
function servicePage(path){
 const pages={
  '/services/architecture':{eyebrow:'ARCHITECT DESIGN',title:'House Plans & Architecture Design',service:'Architect Design',copy:'Browse floor plan concepts and architectural design references for different plot sizes.',images:architecturePlans},
  '/services/interior':{eyebrow:'INTERIOR DESIGN',title:'Interior Design',service:'Interior Design',copy:'Interior concepts for kitchens, wardrobes, living spaces, ceilings and complete homes.',images:interiorImages},
  '/services/turnkey':{eyebrow:'TURNKEY CONSTRUCTION',title:'Construction From Design to Handover',service:'Turnkey Construction',copy:'Construction services and site work references for a coordinated home-building project.',images:constructionImages},
  '/services/vastu':{eyebrow:'VASTU SHASTRA',title:'Vastu Planning',copy:'Vastu planning references for practical home layouts and room placement.',images:[['Vastu Planning','vastu-bg.jpg'],['Vastu Purusha Mandala','vastu-purusha-mandala.webp'],['Vastu-Based Home Design','vastu-guidelince.webp']]}
 };
 const p=pages[path];if(path==='/services/vastu')return vastuPage();if(!p)return `<main>${pageHeader('SERVICE DETAILS','Service information','Explore Divyanshu Infratech services.')}<section class="section">${serviceSection()}</section></main>`;
 return `<main>${pageHeader(p.eyebrow,p.title,p.copy)}${imageGallery(p.title,p.copy,p.images)}<section class="section soft"><div class="wrap card contact-cta"><div><div class="eyebrow">PROJECT ENQUIRY</div><h2>Talk to Our Experts</h2><p>Share your plot details and requirements with Divyanshu Infratech.</p></div><button class="btn service-action" type="button" data-service="${p.service}">Enquire on WhatsApp</button></div></section></main>`
}
function blogs(){return `<main>${pageHeader('DIVYANSHU INFRATECH BLOG','Ideas, Insights & Construction Knowledge','Discover practical construction tips, home design ideas, budgeting advice, Vastu guidelines and architecture insights.')}<section class="section"><div class="filter-tabs">${['All',...new Set(blogsData.map(x=>x.category))].map((x,i)=>`<button class="chip ${i===0?'active':''}" data-blog-filter="${x}">${x}</button>`).join('')}</div><div class="wrap grid project-grid blog-grid">${blogsData.map(x=>`<article class="card blog-card" data-category="${x.category}"><div class="project-art"><img src="/images/${x.image}" alt="${x.title}" loading="lazy"></div><div class="tag">${x.category}</div><h3>${x.title}</h3><p>${x.excerpt}</p><details><summary>Read article</summary><p>${x.content}</p></details></article>`).join('')}</div></section></main>`}
const path=location.pathname.replace(/\/$/,'')||'/';let body=path==='/'?home():path==='/about'?about():path==='/portfolio'?portfolio():path==='/packages'?packages():path==='/contact'?contact():path==='/services'?servicesLanding():path==='/blogs'?blogs():path.startsWith('/services/')?servicePage(path):`<main>${pageHeader('DIVYANSHU INFRATECH','Page not found','Choose a page from the navigation.')}<section class="section">${serviceSection()}</section></main>`;
document.querySelector('#app').innerHTML=nav+body+footer+consultationPopup+serviceVisitPopup;
const consultationDialog=document.querySelector('.consultation-popup');
let showInitialConsultation=false;try{showInitialConsultation=sessionStorage.getItem('divyanshuConsultationSeen')!=='1';if(showInitialConsultation)sessionStorage.setItem('divyanshuConsultationSeen','1')}catch{}if(showInitialConsultation){consultationDialog.classList.add('is-open');document.body.classList.add('consultation-open')}
const closeConsultation=()=>{consultationDialog.classList.remove('is-open');document.body.classList.remove('consultation-open')};
document.querySelectorAll('[data-consultation-open]').forEach(b=>b.addEventListener('click',()=>{consultationDialog.classList.add('is-open');document.body.classList.add('consultation-open');consultationDialog.querySelector('input').focus({preventScroll:true})}));
document.querySelector('.consultation-close').addEventListener('click',closeConsultation);
consultationDialog.addEventListener('click',e=>{if(e.target===consultationDialog)closeConsultation()});
const serviceVisitDialog=document.querySelector('#service-visit-popup');
const closeServiceVisit=()=>{serviceVisitDialog.classList.remove('is-open');document.body.classList.remove('consultation-open')};
document.querySelector('.service-visit-close').addEventListener('click',closeServiceVisit);
serviceVisitDialog.addEventListener('click',e=>{if(e.target===serviceVisitDialog)closeServiceVisit()});
const openServiceVisit=service=>{document.querySelector('#visit-service').value=service;serviceVisitDialog.classList.add('is-open');document.body.classList.add('consultation-open');serviceVisitDialog.querySelector('input').focus({preventScroll:true})};
document.querySelectorAll('.service-action').forEach(b=>b.addEventListener('click',()=>openServiceVisit(b.dataset.service)));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(serviceVisitDialog.classList.contains('is-open'))closeServiceVisit();else if(consultationDialog.classList.contains('is-open'))closeConsultation()}});
if(showInitialConsultation)consultationDialog.querySelector('input').focus({preventScroll:true});
document.querySelector('.menu').addEventListener('click',()=>document.querySelector('.navlinks').classList.toggle('open'));
document.querySelectorAll('.service-visit-form input[aria-label="Payment Amount"]').forEach(i=>i.addEventListener('input',()=>{document.querySelector('.payment-summary strong').textContent=`₹${Number(i.value||0).toLocaleString('en-IN')}`}));
const vastuForm=document.querySelector('#vastu-calculator');if(vastuForm){const vastuResult=document.querySelector('#vastu-result');const initialResult=vastuResult.innerHTML;const facingGuide={North:{entrance:'North / North-East',kitchen:'South-East',bedroom:'South-West',pooja:'North-East',extra:'Keep North and East comparatively open.'},East:{entrance:'East / North-East',kitchen:'South-East',bedroom:'South-West',pooja:'North-East',extra:'Give importance to light and openness toward East.'},South:{entrance:'Carefully selected South-East-side zone',kitchen:'South-East',bedroom:'South-West',pooja:'North-East',extra:'Entrance position needs careful planning; review the exact sector and complete layout.'},West:{entrance:'West / North-West',kitchen:'South-East',bedroom:'South-West',pooja:'North-East',extra:'North-West may work well for entry and parking planning; confirm the exact sector.'}};vastuForm.addEventListener('submit',e=>{e.preventDefault();if(!vastuForm.reportValidity())return;const data=new FormData(vastuForm);const length=Number(data.get('length')),width=Number(data.get('width')),facing=data.get('facing'),guide=facingGuide[facing],area=(length*width).toLocaleString('en-IN',{maximumFractionDigits:2});vastuResult.innerHTML=`<div class="eyebrow">PRELIMINARY VASTU SUGGESTION</div><h2>${length} × ${width} ft · ${area} sq ft</h2><p>Plot facing: <strong>${facing}</strong>. Use these as initial direction-based planning ideas:</p><ul class="vastu-result-list"><li><b>Entrance</b><span>${guide.entrance}</span></li><li><b>Kitchen</b><span>${guide.kitchen}</span></li><li><b>Master bedroom</b><span>${guide.bedroom}</span></li><li><b>Pooja / water</b><span>${guide.pooja}</span></li></ul><p>${guide.extra}</p><p class="vastu-disclaimer">This is preliminary guidance, not a final floor plan. Confirm actual North, site dimensions, setbacks, structure, ventilation and local rules with a qualified professional.</p><a class="btn" target="_blank" rel="noopener noreferrer" href="https://wa.me/919304867172?text=${encodeURIComponent(`Hello Divyanshu Infratech, please review my plot for Vastu planning. Plot: ${length} ft × ${width} ft; facing: ${facing}.`)}">Discuss This Plot on WhatsApp</a>`});vastuForm.addEventListener('reset',()=>queueMicrotask(()=>{vastuResult.innerHTML=initialResult}))}
document.querySelectorAll('form').forEach(f=>{if(f.id==='vastu-calculator')return;f.addEventListener('submit',e=>{e.preventDefault();const fields=[...f.querySelectorAll('input,select')];const message=[`Hello Divyanshu Infratech, I have a ${f.dataset.enquiryType||'project'} enquiry.`,...fields.map(x=>`${x.getAttribute('aria-label')||x.placeholder}: ${x.value}`).filter(x=>!x.endsWith(': '))].join('\n');window.open(`https://wa.me/919304867172?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');if(f.closest('#service-visit-popup'))closeServiceVisit();else if(f.closest('.consultation-popup'))closeConsultation()})});
document.querySelectorAll('.faq-q').forEach(b=>b.addEventListener('click',()=>{const item=b.parentElement;item.classList.toggle('open');b.querySelector('span').textContent=item.classList.contains('open')?'−':'+'}));
document.querySelectorAll('.city-tabs .chip').forEach(b=>b.addEventListener('click',()=>{b.parentElement.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');const n=document.querySelector('.notice');n.textContent=`${b.textContent} selected (preview)`;n.style.display='block';setTimeout(()=>n.style.display='none',1800)}));
document.querySelectorAll('.filter-tabs .chip').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter-tabs .chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.portfolio-card').forEach(c=>c.hidden=b.dataset.filter!=='All'&&c.dataset.category!==b.dataset.filter)}));
document.querySelectorAll('[data-blog-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-blog-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.blog-card').forEach(c=>c.hidden=b.dataset.blogFilter!=='All'&&c.dataset.category!==b.dataset.blogFilter)}));
document.querySelectorAll('.package-choice').forEach(b=>b.addEventListener('click',()=>{const n=document.querySelector('.notice');window.open(`https://wa.me/919304867172?text=${encodeURIComponent('Hello Divyanshu Infratech, I am interested in the '+b.textContent.trim()+' package.')}`,'_blank','noopener,noreferrer')}));

const pageTitle=({ '/':'Divyanshu Infratech | Home Construction & Design','/about':'About Divyanshu Infratech','/portfolio':'Projects | Divyanshu Infratech','/packages':'Construction Packages | Divyanshu Infratech','/contact':'Contact Divyanshu Infratech'})[path]||`Divyanshu Infratech | ${document.querySelector('main h1')?.textContent||'Home Construction'}`;document.title=pageTitle;const pageDescription=`Divyanshu Infratech offers home construction, architecture, interior design and turnkey services in Biharsharif, Nalanda, Bihar.`;const metaDescription=document.querySelector('meta[name=description]');if(metaDescription)metaDescription.content=pageDescription;for(const key of ['og:title','twitter:title']){let tag=document.querySelector(`meta[property='${key}'],meta[name='${key}']`);if(tag)tag.content=pageTitle}for(const key of ['og:description','twitter:description']){let tag=document.querySelector(`meta[property='${key}'],meta[name='${key}']`);if(tag)tag.content=pageDescription}
